import * as React from "react";
import { cn } from "@/lib/utils";

export interface RatingProps extends React.HTMLAttributes<HTMLDivElement> {
  value?: number;
  max?: number;
  onChange?: (val: number) => void;
  shape?: 'star' | 'heart';
  animationType?: 'bloom-expand' | 'smooth-pulse' | 'harmonic-wave';
  inkColor?: string;
}

export const Rating: React.FC<RatingProps> = ({ value = 5, max = 5, onChange, shape = 'star', className, ...props }) => {
  return (
    <div className={cn("inline-flex gap-1.5 cursor-pointer font-mono", className)} {...props}>
      {Array.from({ length: max }).map((_, i) => (
        <span key={i} onClick={() => onChange?.(i + 1)} className={cn("text-xl transition-transform hover:scale-125", i < value ? "opacity-100" : "opacity-30")}>
          {shape === 'heart' ? '♥' : '★'}
        </span>
      ))}
    </div>
  );
};
